const rawBody = $json.body ?? $json;
const message = (rawBody.message ?? rawBody.text ?? '').toString().trim();
const userId = (rawBody.userId ?? rawBody.user ?? 'anonymous').toString().trim();
const sessionId = (rawBody.sessionId ?? rawBody.conversationId ?? userId).toString().trim();
const userContext = rawBody.userContext ?? {};
const modo = (rawBody.modo ?? 'auto').toString().toLowerCase().trim();

const rawImages = Array.isArray(rawBody.imageAttachments)
  ? rawBody.imageAttachments
  : (Array.isArray(rawBody.images) ? rawBody.images : []);
const imageAttachments = rawImages
  .filter((item) => item && (item.dataUrl || item.imageUrl || item.url || item.signedUrl) && item.type && item.type.startsWith('image/'))
  .slice(0, 4)
  .map((item) => {
    const imageUrl = (item.dataUrl || item.imageUrl || item.url || item.signedUrl || '').toString();
    return {
      name: (item.name ?? 'imagem').toString(),
      type: (item.type ?? 'image/*').toString(),
      size: Number(item.size ?? 0),
      signedUrl: (item.signedUrl || item.imageUrl || item.url || imageUrl).toString(),
      imageUrl,
      url: imageUrl,
      dataUrl: item.dataUrl ? item.dataUrl.toString() : undefined,
    };
  });

const rawDocuments = Array.isArray(rawBody.documentAttachments)
  ? rawBody.documentAttachments
  : (Array.isArray(rawBody.documents) ? rawBody.documents : []);
const documentAttachments = rawDocuments
  .filter((item) => item && item.name && item.type)
  .slice(0, 4)
  .map((item) => ({
    name: (item.name ?? 'documento').toString(),
    type: (item.type ?? 'application/octet-stream').toString(),
    size: Number(item.size ?? 0),
    signedUrl: (item.signedUrl || item.url || '').toString(),
    url: (item.url || item.signedUrl || '').toString(),
    text: item.text ? item.text.toString() : '',
    extractionError: item.extractionError ? item.extractionError.toString() : '',
  }));

const rawAudios = Array.isArray(rawBody.audioAttachments)
  ? rawBody.audioAttachments
  : (Array.isArray(rawBody.audios) ? rawBody.audios : []);
const audioAttachments = rawAudios
  .filter((item) => item && item.name && item.type)
  .slice(0, 3)
  .map((item) => ({
    name: (item.name ?? 'audio').toString(),
    type: (item.type ?? 'audio/*').toString(),
    size: Number(item.size ?? 0),
    signedUrl: (item.signedUrl || item.url || '').toString(),
    url: (item.url || item.signedUrl || '').toString(),
    text: item.text ? item.text.toString() : '',
    provider: item.provider ? item.provider.toString() : '',
    model: item.model ? item.model.toString() : '',
    language: item.language ? item.language.toString() : '',
    confidence: Number(item.confidence ?? 0) || undefined,
    transcriptionError: item.transcriptionError ? item.transcriptionError.toString() : '',
  }));

const documentContext = rawBody.documentContext || null;
const documentCtxString = (rawBody.documentCtxString || documentContext?.text || '').toString().trim();
const audioContext = rawBody.audioContext || null;
const audioCtxString = (rawBody.audioCtxString || audioContext?.text || '').toString().trim();
const visualContext = rawBody.visualContext || null;
const visualCtxString = (rawBody.visualCtxString || '').toString().trim();

if (!message && imageAttachments.length === 0 && documentAttachments.length === 0 && audioAttachments.length === 0) {
  return [{ ok: false, error: "Missing 'message'" }];
}

const memoryKey = userId + '__' + sessionId;
return [{
  ok: true,
  message,
  userId,
  sessionId,
  memoryKey,
  userContext,
  modo,
  imageAttachments,
  hasImages: imageAttachments.length > 0 || rawBody.hasImages === true,
  visualContext,
  visualCtxString,
  usedVision: rawBody.usedVision === true || Boolean(visualContext || visualCtxString),
  documentAttachments,
  documentContext,
  documentCtxString,
  hasDocuments: documentAttachments.length > 0 || rawBody.hasDocuments === true || Boolean(documentContext || documentCtxString),
  audioAttachments,
  audioContext,
  audioCtxString,
  hasAudio: audioAttachments.length > 0 || rawBody.hasAudio === true || Boolean(audioContext || audioCtxString),
  usedAudioTranscription: rawBody.usedAudioTranscription === true || Boolean(audioContext || audioCtxString),
  receivedAt: new Date().toISOString(),
}];

