const routedInput = $('Fast Router').item.json;
const classifierResponse = $json;

let cls = routedInput.fastRoute?.classifier || {};
if (!routedInput.fastRoute?.skipClassifier) {
  try {
    const raw = classifierResponse.choices[0].message.content.trim();
    const fence = String.fromCharCode(96, 96, 96);
    const clean = raw.replace(new RegExp(fence + 'json|' + fence, 'g'), '').trim();
    cls = JSON.parse(clean);
  } catch {
    cls = routedInput.fastRoute?.classifier || {
      tipo:'geral', area:'geral', complexidade:'media', usarBase:false,
      usarMemoria:true, modo_sugerido:'corvus', ehSimulacao:false, ehDecisao:false
    };
  }
}

const validModes = ['corvus','fenrir','cipher','conselho','simulacao'];
const modoManual = routedInput.modo;
let resolvedMode = validModes.includes(modoManual) ? modoManual : (cls.modo_sugerido || 'corvus');
if (cls.ehSimulacao && modoManual === 'auto') resolvedMode = 'simulacao';
if (resolvedMode === 'conselho' && cls.complexidade !== 'alta') resolvedMode = 'cipher';

const topKMap = { baixa: 3, media: 5, alta: 8 };
const topK = topKMap[cls.complexidade] || 5;
const baseConf = { baixa: 0.92, media: 0.78, alta: 0.65 };
const typeMod = { pergunta:0.05, decisao:-0.05, simulacao:-0.10, ideia:-0.08, criativo:-0.06, problema:0, geral:0 };
const fastConfidence = routedInput.fastRoute?.confidence || 0;
const estimatedConfidence = Math.min(0.99, Math.max(0.40,
  fastConfidence || ((baseConf[cls.complexidade] || 0.75) + (typeMod[cls.tipo] || 0))
)).toFixed(2);

const userContext = routedInput.userContext || {};
const userCtxString = [
  'Nome: ' + (userContext.nome || 'Desconhecido'),
  'Cargo: ' + (userContext.cargo || '-'),
  'Sigla: ' + (userContext.sigla || '-'),
  'Tipo: ' + (userContext.tipo || 'convidado')
].join(' | ');

const visualContext = routedInput.visualContext || null;
const documentContext = routedInput.documentContext || null;
const documentCtxString = (routedInput.documentCtxString || documentContext?.text || '').toString();
const audioContext = routedInput.audioContext || null;
const audioCtxString = (routedInput.audioCtxString || audioContext?.text || '').toString();
const visualCtxString = routedInput.visualCtxString
  || (visualContext
    ? [
        'OCR: ' + (visualContext.ocrText || 'sem texto detectado'),
        'Descricao: ' + (visualContext.description || ''),
        'Itens: ' + ((visualContext.relevantItems || []).join(', ') || '-'),
        'Limitacoes: ' + (visualContext.limitations || '-')
      ].join('\n')
    : '');

return [{
  message: routedInput.message,
  userId: routedInput.userId,
  sessionId: routedInput.sessionId,
  memoryKey: routedInput.memoryKey,
  userContext,
  userCtxString,
  visualContext,
  visualCtxString,
  usedVision: Boolean(visualContext || visualCtxString),
  imageAttachments: routedInput.imageAttachments || [],
  documentContext,
  documentCtxString,
  hasDocuments: Boolean(documentCtxString),
  documentAttachments: routedInput.documentAttachments || [],
  audioContext,
  audioCtxString,
  hasAudio: Boolean(audioCtxString),
  usedAudioTranscription: Boolean(audioContext || audioCtxString),
  audioAttachments: routedInput.audioAttachments || [],
  receivedAt: routedInput.receivedAt,
  visionError: routedInput.visionError || '',
  orchestrator: {
    tipo: cls.tipo || 'geral', area: cls.area || 'geral',
    complexidade: cls.complexidade || 'media',
    usarBase: cls.usarBase !== false,
    usarMemoria: cls.usarMemoria !== false,
    modoSugerido: cls.modo_sugerido || 'corvus',
    ehSimulacao: cls.ehSimulacao === true,
    ehDecisao: cls.ehDecisao === true,
    requestedMode: routedInput.modo,
    resolvedMode,
    topK,
    fastPath: routedInput.fastRoute?.skipClassifier === true,
    estimatedConfidence: parseFloat(estimatedConfidence)
  }
}];

const agentOutput = $input.first().json;
let oc = {};
try { oc = agentOutput.orchestrator || JSON.parse(agentOutput.orchestratorData || '{}'); } catch {}
if (oc.ehDecisao === true) {
  console.log('[corvus:decision]', JSON.stringify({
    msg: (agentOutput.message||'').substring(0,200),
    tipo: oc.tipo, area: oc.area, modo: oc.resolvedMode, ts: new Date().toISOString()
  }));
}
return [agentOutput];

const agentOutput = $input.first()?.json || {};

let oc = {};
try {
  oc = agentOutput.orchestrator || JSON.parse(agentOutput.orchestratorData || '{}');
} catch {}

const resolvedMode = agentOutput.resolvedMode || oc.resolvedMode || 'corvus';
const modeLabels = {
  corvus:'Corvus - Institucional', fenrir:'Fenrir - Criativo',
  cipher:'Cipher - Estrategico', conselho:'Conselho - Perspectiva Tripla',
  simulacao:'Simulacao - Analise de Cenarios'
};

function parseMaybeJson(value, fallback = null) {
  if (!value) return fallback;
  if (typeof value === 'object') return value;
  try { return JSON.parse(value); } catch { return fallback; }
}

const base = oc.estimatedConfidence || 0.75;
const ragBonus = oc.usarBase ? 0.05 : 0;
const cxPenalty = oc.complexidade === 'alta' ? -0.08 : (oc.complexidade === 'baixa' ? 0.04 : 0);
const confidence = Math.min(0.99, Math.max(0.40, base + ragBonus + cxPenalty));
const visualContext = parseMaybeJson(agentOutput.visualContext, agentOutput.visualContext || null);
const documentContext = parseMaybeJson(agentOutput.documentContext, agentOutput.documentContext || null);
const audioContext = parseMaybeJson(agentOutput.audioContext, agentOutput.audioContext || null);
const usedVision = Boolean(agentOutput.usedVision || visualContext || agentOutput.visualCtxString);
const usedDocuments = Boolean(agentOutput.hasDocuments || agentOutput.documentCtxString || documentContext);
const usedAudio = Boolean(agentOutput.hasAudio || agentOutput.audioCtxString || audioContext);
const audioSummary = (agentOutput.audioCtxString || audioContext?.text || '').toString().slice(0, 240);
const documentSummary = (agentOutput.documentCtxString || documentContext?.text || '').toString().slice(0, 240);

const suggestionsMap = {
  decisao: ['Simular cenario', 'Ver alternativas', 'Analisar riscos com Cipher'],
  problema: ['Analisar com Cipher', 'Simular solucao', 'Consultar Conselho'],
  ideia: ['Expandir com Fenrir', 'Analisar viabilidade', 'Simular impacto'],
  audio: ['Transcrever integralmente', 'Resumir audio', 'Extrair acoes'],
  simulacao: ['Analisar decisao', 'Consultar Conselho', 'Salvar como decisao'],
  conselho: ['Aprofundar com Cipher', 'Expandir com Fenrir', 'Simular cenario'],
  geral: ['Gerar ideia', 'Analisar decisao', 'Simular cenario']
};
const suggestions = suggestionsMap[oc.tipo] || suggestionsMap.geral;

function cleanText(value) {
  return (value || '').toString().replace(/\s+/g, ' ').trim();
}
function makeTags() {
  const tags = new Set();
  if (oc.area && oc.area !== 'geral') tags.add(oc.area);
  if (oc.tipo && oc.tipo !== 'geral') tags.add(oc.tipo);
  if (resolvedMode && resolvedMode !== 'corvus') tags.add(resolvedMode);
  if (usedVision) tags.add('imagem');
  if (usedDocuments) tags.add('documento');
  if (usedAudio) tags.add('audio');
  if (oc.usarBase) tags.add('msy');
  return Array.from(tags).slice(0, 5);
}
function makeNextActions(reply) {
  const lines = reply.split('
').map(cleanText).filter(Boolean);
  const actionLines = lines.filter((line) => /^(\d+\.|-|\*)?\s*(definir|validar|revisar|criar|enviar|priorizar|analisar|executar|documentar|alinhar)/i.test(line));
  return (actionLines.length ? actionLines : suggestions).slice(0, 4);
}
function makeMeta(replyText, mode) {
  return {
    agent:'Corvus 3.2 Beta', model:'gpt-4o', mode,
    modeLabel: modeLabels[mode] ?? mode,
    complexity: oc.complexidade || 'media', usedRAG: oc.usarBase === true,
    usedVision, visualSummary: visualContext?.description || '',
    usedDocuments, documentSummary,
    usedAudio, audioSummary,
    confidence: parseFloat(confidence.toFixed(2)), tipo: oc.tipo || 'geral',
    summaryCandidate: cleanText(replyText).slice(0, 360),
    tags: makeTags(),
    nextActions: makeNextActions(replyText),
    decisionCandidate: oc.ehDecisao === true,
    timestamp: new Date().toISOString(), suggestions, visionError: agentOutput.visionError || ''
  };
}

if (agentOutput.consiliumPayload?.isConselho) {
  const consiliumText = agentOutput.consiliumPayload.blocks.map((block) => block.label + ': ' + block.reply).join('
');
  return [{
    json: {
      ok: true,
      reply: consiliumText,
      consilium: agentOutput.consiliumPayload.blocks,
      meta: { ...makeMeta(consiliumText, 'conselho'), usedRAG: oc.usarBase || false }
    }
  }];
}

let reply = (
  agentOutput.reply ?? agentOutput.output ?? agentOutput.text ?? agentOutput.response ??
  agentOutput.message ?? (agentOutput.choices && agentOutput.choices[0]?.message?.content) ?? ''
).toString().trim();

if (!reply && usedAudio && audioSummary) {
  reply = [
    'Recebi e transcrevi o audio. O workflow nao retornou uma resposta do agente, entao segue a transcricao para continuidade:',
    '',
    audioSummary
  ].join('
');
}

if (!reply) {
  reply = 'Recebi a mensagem, mas o agente nao retornou uma resposta. Verifique o ultimo node executado no n8n.';
}

return [{
  json: {
    ok: true,
    reply,
    consilium: null,
    meta: makeMeta(reply, resolvedMode)
  }
}];

const d = $json;
const titulo   = (d['Titulo']   || '').trim();
const conteudo = (d['Conteudo'] || '').trim();
const categoria= (d['Categoria']|| 'Geral').trim();
const tagsRaw  = (d['Tags']     || '').trim();
const tags     = tagsRaw ? tagsRaw.split(',').map(t => t.trim()).filter(Boolean) : [];
const texto    = titulo + '\n\n' + conteudo;
return [{ titulo, conteudo, categoria, tags, texto }];

const prep      = $('Preparar').item.json;
const embedding = $json.data[0].embedding;
return [{
  titulo:    prep.titulo,
  conteudo:  prep.conteudo,
  categoria: prep.categoria,
  tags:      prep.tags,
  embedding: '[' + embedding.join(',') + ']'
}];

const d  = $input.first().json;
const oc = d.orchestrator;

const baseInst = oc.usarBase
  ? 'Consulte o contexto institucional da MSY: valores, estrutura, membros, histÃ³ria.'
  : 'Responda com base no conhecimento geral da Ordem Masayoshi.';

const ctx = `UsuÃ¡rio: ${d.userCtxString}\nTipo: ${oc.tipo} | Ãrea: ${oc.area} | Complexidade: ${oc.complexidade}`;

const sCorvus = `VocÃª Ã© CORVUS â€” agente institucional da Ordem Masayoshi. ${baseInst}\n${ctx}\nResposta precisa, direta e institucional. Para perguntas simples, responda curto. Para comparacao, explicacao, ranking, decisao, plano, estudo, diagnostico, estrategia ou analise, entregue resposta premium: sintese objetiva, estrutura visual clara, tabelas quando houver comparacao real, criterios quando precisar avaliar opcoes, ranking quando existir hierarquia, checklist ou plano de acao quando houver execucao, e conclusao/recomendacao/proximos passos. Nao exponha raciocinio interno literal. Se o pedido usar compare, comparativo, ranking, maior para menor, melhores, hierarquia, cargos, funcoes ou diferencas, use obrigatoriamente tabela markdown com colunas claras; nao use lista numerada para comparativos que cabem em tabela.`;
const sFenrir = `VocÃª Ã© CORVUS modo FENRIR â€” lado criativo da Ordem Masayoshi. ${baseInst}\n${ctx}\nVisÃ£o criativa, expansiva, inspiradora. MÃ¡ximo 8 linhas.`;
const sCipher = `VocÃª Ã© CORVUS modo CIPHER â€” estrategista da Ordem Masayoshi. ${baseInst}\n${ctx}\nEstruture: **AnÃ¡lise** â†’ **Riscos** â†’ **RecomendaÃ§Ã£o** â†’ **PrÃ³ximos Passos**.`;

// PrÃ©-serializa os bodies completos â€” evita problema de expressÃ£o dentro de JSON
const bodyCorvus = JSON.stringify({
  model:'gpt-4o', temperature:0.3, max_tokens:1200,
  messages:[{role:'system',content:sCorvus},{role:'user',content:d.message}]
