  _orchestrator:  JSON.stringify(oc),
  _bodyCorvus:    bodyCorvus,
  _bodyFenrir:    bodyFenrir,
  _bodyCipher:    bodyCipher
}];

const d = $input.first().json;

const safeTrim = (v) => (v || '').toString().trim() || 'Sem resposta.';

const replyCorvus = safeTrim($('Set Cipher Body').item.json._replyCorvus);
const replyFenrir = safeTrim($('Set Cipher Body').item.json._replyFenrir);
const replyCipher = safeTrim(d.choices && d.choices[0]?.message?.content);

let oc = {};
try { oc = JSON.parse($('Set Cipher Body').item.json._orchestrator || '{}'); } catch {}

return [{
  consiliumPayload: {
    isConselho: true,
    blocks: [
      { mode:'corvus', label:'â¬¡ Corvus', reply: replyCorvus },
      { mode:'fenrir', label:'âš¡ Fenrir', reply: replyFenrir },
      { mode:'cipher', label:'â—ˆ Cipher', reply: replyCipher }
    ]
  },
  orchestrator: oc,
  resolvedMode: 'conselho',
  message:   $('Set Cipher Body').item.json._message,
  userId:    $('Set Cipher Body').item.json._userId,
  sessionId: $('Set Cipher Body').item.json._sessionId
}];

const base = $('Normalize Input').item.json;
const raw = $json;

function firstText(value) {
  if (typeof value?.output_text === 'string') return value.output_text;
  const output = Array.isArray(value?.output) ? value.output : [];
  for (const item of output) {
    const content = Array.isArray(item.content) ? item.content : [];
    for (const part of content) {
      if (typeof part.text === 'string') return part.text;
      if (typeof part.value === 'string') return part.value;
    }
  }
  return '';
}

function parseJson(text) {
  try { return JSON.parse(text); } catch {}
  const fence = String.fromCharCode(96, 96, 96);
  const clean = text
    .replace(new RegExp('^' + fence + '(?:json)?', 'i'), '')
    .replace(new RegExp(fence + '$', 'i'), '')
    .trim();
  try { return JSON.parse(clean); } catch {}
  return null;
}

const text = firstText(raw).trim();
if (!text) {
  return [{
    ...base,
    visualContext: base.visualContext || null,
    visualCtxString: base.visualCtxString || '',
    usedVision: Boolean(base.visualContext || base.visualCtxString),
    visionError: raw.error?.message || raw.message || 'Vision Analyzer nao retornou contexto visual.',
  }];
}

const parsed = parseJson(text) || {};
const visualContext = {
  ocrText: (parsed.ocrText || parsed.ocr || '').toString().trim(),
  description: (parsed.description || parsed.descricao || text || '').toString().trim(),
  relevantItems: Array.isArray(parsed.relevantItems) ? parsed.relevantItems.slice(0, 8) : [],
  limitations: (parsed.limitations || parsed.limits || '').toString().trim(),
  confidence: Number(parsed.confidence || parsed.confianca || 0.7),
};
const visualCtxString = [
  'OCR: ' + (visualContext.ocrText || 'sem texto detectado'),
  'Descricao: ' + (visualContext.description || ''),
  'Itens: ' + ((visualContext.relevantItems || []).join(', ') || '-'),
  'Limitacoes: ' + (visualContext.limitations || '-'),
  Number.isFinite(visualContext.confidence) ? 'Confianca: ' + visualContext.confidence : '',
].filter(Boolean).join('\n');

return [{ ...base, visualContext, visualCtxString, usedVision: Boolean(visualCtxString), hasImages: true }];

const item = $json;
const text = (item.message || '').toString();
const lower = text.toLowerCase();
const visual = item.visualContext || null;
const docs = item.documentContext || null;
const audio = item.audioContext || null;
const documentText = (item.documentCtxString || docs?.text || '').toString();
const audioText = (item.audioCtxString || audio?.text || '').toString();
const combinedText = [text, documentText, audioText].join(' ');
const combinedLower = combinedText.toLowerCase();
const hasVision = Boolean(visual?.description || visual?.ocrText || item.visualCtxString);
const hasDocuments = Boolean(documentText);
const hasAudio = Boolean(audioText);

const institutionalWords = ['msy','masayoshi','ordem','membro','cargo','lideranca','liderança','evento','valores','nevermind','britannia','corvus'];
const decisionWords = ['decidir','decisao','decisão','risco','estrategia','estratégia','aprovar','planejar','prioridade','problema'];
const creativeWords = ['ideia','crie','campanha','texto','roteiro','post','criativo','brainstorm'];
const simulationWords = ['e se','simula','simular','imagine que','o que aconteceria','cenario','cenário'];

const hasInstitutional = institutionalWords.some((word) => combinedLower.includes(word));
const hasDecision = decisionWords.some((word) => combinedLower.includes(word));
const hasCreative = creativeWords.some((word) => combinedLower.includes(word));
const hasSimulation = simulationWords.some((word) => combinedLower.includes(word));
const shortCasual = combinedLower.length <= 80 && /^(oi|ola|olá|bom dia|boa tarde|boa noite|valeu|obrigado|teste) /.test(combinedLower);
const manualMode = ['corvus','fenrir','cipher','conselho','simulacao'].includes(item.modo) ? item.modo : '';

let tipo = hasAudio ? 'audio' : 'geral';
let area = hasInstitutional ? 'estrutura' : 'geral';
let complexidade = combinedLower.length > 550 || hasDecision ? 'alta' : (combinedLower.length > 180 ? 'media' : 'baixa');
let modo_sugerido = manualMode || 'corvus';
if (!manualMode && hasSimulation) modo_sugerido = 'simulacao';
else if (!manualMode && hasCreative) modo_sugerido = 'fenrir';
else if (!manualMode && hasDecision) modo_sugerido = 'cipher';

if (hasSimulation) tipo = 'simulacao';
else if (hasDecision) tipo = 'decisao';
else if (hasCreative) tipo = 'ideia';
else if (hasInstitutional) tipo = 'pergunta';
else if (hasAudio) tipo = 'audio';

const visualText = (visual?.ocrText || '') + ' ' + (visual?.description || '') + ' ' + documentText + ' ' + audioText;
const classifier = {
  tipo,
  area,
  complexidade,
  usarBase: hasInstitutional || (hasVision && /msy|masayoshi|ordem|cargo|membro/i.test(visualText)) || (hasAudio && /msy|masayoshi|ordem|cargo|membro/i.test(audioText)),
  usarMemoria: !shortCasual,
